const inicio = Date.now();
const fonte = $json.fonte;
const janela = $json.janela;
const modo = $json.modo;
const versaoApi = 'v21.0';

const contaDeAnuncio = String(fonte.externalId);
const limite = modo === 'amostra' ? 500 : 5000;
const campos = ['campaign_id', 'campaign_name', 'date_start', 'spend', 'impressions', 'clicks', 'actions', 'action_values'].join(',');
const timeRange = encodeURIComponent(JSON.stringify({ since: janela.start, until: janela.end }));
const url = `https://graph.facebook.com/${versaoApi}/${contaDeAnuncio}/insights?level=campaign&time_increment=1&time_range=${timeRange}&fields=${campos}&limit=${limite}`;

function devolver(linhas, falhas, requests, bytes) {
  return [{
    json: {
      linhas,
      volumetria: { linhas: linhas.length, bytes, requests, duracaoMs: Date.now() - inicio },
      falhas,
      requests,
      versaoApi,
    },
  }];
}

let resposta;
try {
  resposta = await this.helpers.httpRequestWithAuthentication.call(this, 'facebookGraphApi', {
    method: 'GET',
    url,
    json: true,
    returnFullResponse: true,
    ignoreHttpStatusErrors: true,
  });
} catch (erro) {
  return devolver([], [{ causa: 'api_recusou', detalhe: `falha de rede: ${erro.message}` }], 1, 0);
}

if (resposta.statusCode === 401 || resposta.statusCode === 403) {
  const detalhe = resposta.body?.error?.message || `HTTP ${resposta.statusCode}`;
  return devolver([], [{ causa: 'reauth_pending', detalhe }], 1, 0);
}

if (resposta.statusCode < 200 || resposta.statusCode >= 300) {
  const codigoMeta = resposta.body?.error?.code;
  const causa = codigoMeta === 190 ? 'reauth_pending' : 'api_recusou';
  const detalhe = resposta.body?.error?.message || `HTTP ${resposta.statusCode}`;
  return devolver([], [{ causa, detalhe }], 1, 0);
}

function somarAcoes(lista, tipo) {
  const item = (lista ?? []).find((acao) => acao.action_type === tipo);
  return item ? Number(item.value ?? 0) : 0;
}

const linhasBrutas = resposta.body?.data ?? [];
const bytes = JSON.stringify(resposta.body).length;

const linhas = linhasBrutas.map((linha) => ({
  externalCampaignId: String(linha.campaign_id ?? ''),
  campaignName: linha.campaign_name ?? null,
  metricDate: linha.date_start ?? null,
  spend: Number(linha.spend ?? 0),
  impressions: Number(linha.impressions ?? 0),
  clicks: Number(linha.clicks ?? 0),
  conversions: somarAcoes(linha.actions, 'purchase') || somarAcoes(linha.actions, 'offsite_conversion.fb_pixel_purchase'),
  revenue: somarAcoes(linha.action_values, 'purchase') || somarAcoes(linha.action_values, 'offsite_conversion.fb_pixel_purchase'),
  currency: fonte.currency || 'BRL',
}));

if (linhas.length === 0) {
  return devolver([], [{ causa: 'sem_dados_no_periodo', detalhe: null }], 1, bytes);
}

return devolver(linhas, [], 1, bytes);
